parameters.jsCode:
const body = $json.body ?? $json;
const headers = $json.headers ?? {};
const expectedSecret = $env.N8N_WEBHOOK_SECRET;
const receivedSecret = headers['x-lumi-webhook-secret'] || headers['X-Lumi-Webhook-Secret'];

if (expectedSecret && receivedSecret !== expectedSecret) {
  throw new Error('Unauthorized webhook request');
}

function cleanText(value) {
  return String(value ?? '').trim();
}

function cleanName(value) {
  return cleanText(value)
    .replace(/[^\p{L}' -]/gu, '')
    .replace(/\s{2,}/g, ' ')
    .replace(/-{2,}/g, '-')
    .slice(0, 40);
}

function cleanPhone(value) {
  const text = cleanText(value);
  const hasPlus = text.startsWith('+');
  const digits = text.replace(/\D/g, '').slice(0, 15);
  return `${hasPlus ? '+' : ''}${digits}`;
}

const clientName = cleanName(body.clientName || body.name);
const phone = cleanPhone(body.phone);
const serviceTitle = cleanText(body.serviceTitle || body.service);
const visitDate = cleanText(body.visitDate || body.date);
const visitTime = cleanText(body.visitTime || body.time || 'уточнить');
const leadId = body.id || `LUMI-${Date.now().toString(36).toUpperCase()}`;

if (!/^[\p{L}][\p{L}' -]{1,39}$/u.test(clientName)) {
  throw new Error('Invalid client name');
}

if (!/^\+?[0-9]{10,15}$/.test(phone)) {
  throw new Error('Invalid phone');
}

if (!/^\d{4}-\d{2}-\d{2}$/.test(visitDate)) {
  throw new Error('Invalid visit date');
}

const reminderAt = new Date(`${visitDate}T10:00:00+07:00`);
reminderAt.setDate(reminderAt.getDate() - 1);

return [{
  json: {
    leadId,
    createdAt: cleanText(body.createdAt) || new Date().toLocaleString('ru-RU', { timeZone: 'Asia/Novosibirsk' }),
    clientName,
    phone,
    serviceTitle,
    price: cleanText(body.price || 'уточнить'),
    master: cleanText(body.master || 'любой свободный мастер'),
    visitDate,
    visitTime,
    status: cleanText(body.status || 'new'),
    source: cleanText(body.source || 'landing_form'),
    telegramChatId: cleanText(body.telegramChatId),
    reminderAt: reminderAt.toISOString()
  }
}];

const lead = $items('Normalize + Validate')[0].json;
const rows = $input.all().map((item) => item.json);

function normalizePhone(value) {
  return String(value ?? '').replace(/\D/g, '');
}

const phone = normalizePhone(lead.phone);
const duplicate = rows.some((row) => {
  const rowPhone = normalizePhone(row['Телефон'] || row.phone || row.Phone);
  const rowDate = String(row['Дата визита'] || row.visitDate || row.date || '');
  const rowStatus = String(row['Статус'] || row.status || '').toLowerCase();
  return rowPhone === phone && rowDate === lead.visitDate && rowStatus !== 'cancelled';
});

return [{
  json: {
    ...lead,
    isDuplicate: duplicate,
    duplicateReason: duplicate ? 'same phone and visit date already exists' : ''
  }
}];

